begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_health_partner_profiles(organization_id uuid primary key references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,facility_type text not null,departments text[] not null default '{}',maternity_activity boolean not null default false,family_volume int,waiting_areas jsonb not null default '{}',clinical_contact_id uuid references public.angelcare_marketplace_b2b_contacts(id),safeguarding_contact_id uuid references public.angelcare_marketplace_b2b_contacts(id),privacy_requirements jsonb not null default '{}',non_medical_acknowledged boolean not null default false,acknowledged_by uuid,acknowledged_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_health_support_boundaries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,program_id uuid references public.angelcare_marketplace_b2b_programs(id) on delete cascade,boundary_key text not null,title_fr text not null,allowed boolean not null default false,requires_licensed_referral boolean not null default true,prohibited_actions text[] not null default array['diagnosis','prescription','medical treatment','medication administration']::text[],escalation_rule text not null,status text not null default 'draft' check(status in('draft','review','approved','rejected','suspended','archived')),approved_by uuid,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,program_id,boundary_key));
create table if not exists public.angelcare_marketplace_health_referral_protocols(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,protocol_key text not null,title_fr text not null,trigger_conditions jsonb not null default '[]',referral_role text not null,licensed_contact_id uuid references public.angelcare_marketplace_b2b_contacts(id),maximum_response_minutes int,documentation_required boolean not null default true,status text not null default 'draft' check(status in('draft','review','approved','active','suspended','archived')),approved_by uuid,approved_at timestamptz,unique(organization_id,protocol_key));
create table if not exists public.angelcare_marketplace_health_consent_requirements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,consent_type text not null,required boolean not null default true,consent_text_key text not null,retention_days int,escalation_contact_id uuid references public.angelcare_marketplace_b2b_contacts(id),status text not null default 'draft' check(status in('draft','translation_review','legal_review','approved','rejected','archived')),approved_by uuid,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,consent_type));
create table if not exists public.angelcare_marketplace_health_incident_referrals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),program_id uuid references public.angelcare_marketplace_b2b_programs(id),protocol_id uuid references public.angelcare_marketplace_health_referral_protocols(id),incident_reference text not null,trigger_summary text not null,referral_contact_id uuid,initiated_at timestamptz not null default now(),acknowledged_at timestamptz,resolved_at timestamptz,status text not null default 'initiated' check(status in('initiated','acknowledged','transferred','resolved','cancelled')),evidence jsonb not null default '{}');
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values('marketplace.b2b.health_partners.view','Voir partenaires santé','B2B Health-Adjacent',false),('marketplace.b2b.health_partners.manage','Gérer programmes non médicaux','B2B Health-Adjacent',true),('marketplace.b2b.health_partners.compliance_review','Réviser limites, consentements et referrals','B2B Health-Adjacent',true),('marketplace.b2b.health_partners.sensitive_approve','Approuver les contenus sensibles','B2B Health-Adjacent',true) on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.b2b.health_partners.%' on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/admin/verticals/health-partners',required_permissions=array['marketplace.b2b.health_partners.view']::text[],version=version+1,updated_at=now() where introduced_by_mega_zip=14;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.b2b.health-adjacent.enabled','Maternity & Health-Adjacent Support','Accompagnement strictement non médical, consentement et referral.',true,'active','Ultra Delivery 3/5 · Original MZ14') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_health_partner_profiles enable row level security;alter table public.angelcare_marketplace_health_support_boundaries enable row level security;alter table public.angelcare_marketplace_health_referral_protocols enable row level security;alter table public.angelcare_marketplace_health_consent_requirements enable row level security;alter table public.angelcare_marketplace_health_incident_referrals enable row level security;
revoke all on table public.angelcare_marketplace_health_partner_profiles,public.angelcare_marketplace_health_support_boundaries,public.angelcare_marketplace_health_referral_protocols,public.angelcare_marketplace_health_consent_requirements,public.angelcare_marketplace_health_incident_referrals from anon,authenticated;grant all on table public.angelcare_marketplace_health_partner_profiles,public.angelcare_marketplace_health_support_boundaries,public.angelcare_marketplace_health_referral_protocols,public.angelcare_marketplace_health_consent_requirements,public.angelcare_marketplace_health_incident_referrals to service_role;
commit;
